  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  overflow: hidden;
  border: 1px solid ${TRANSPARENT.GRAY[100]};
  border-radius: 12px;
  box-shadow: ${BOX_SHADOW.HOME_CARD};
  color: inherit;
  text-decoration: none;
`;

