it('renders card slides with the Figma carousel navigation pill', () => {
  render(<Ad variant='card-large' items={[{ title: '첫 카드' }, { title: '두 번째 카드' }]} />);

  expect(getComputedStyle(screen.getByTestId('ad-card-large')).position).toBe('relative');
  expect(screen.queryByTestId('ad-card-nav-card-large')).not.toBeNull();
  expect(screen.queryByRole('button', { name: '이전 광고' })).not.toBeNull();
  expect(screen.queryByRole('button', { name: '다음 광고' })).not.toBeNull();
});

it('moves card slides with the card carousel arrows', () => {
  render(<Ad variant='card-large' items={[{ title: '첫 카드' }, { title: '두 번째 카드' }]} />);

  const track = screen.getByTestId('ad-track-card-large');
  expect(track.getAttribute('style')).toContain('translateX(-0%)');

  act(() => {
    screen.getByRole('button', { name: '다음 광고' }).click();
  });

  expect(track.getAttribute('style')).toContain('translateX(-100%)');
});

