it('renders card slides without carousel navigation arrows', () => {
  render(<Ad variant='card-large' items={[{ title: '첫 카드' }, { title: '두 번째 카드' }]} />);

  expect(getComputedStyle(screen.getByTestId('ad-card-large')).position).toBe('relative');
  expect(screen.queryByTestId('ad-card-nav-card-large')).toBeNull();
  expect(screen.queryByRole('button', { name: '이전 광고' })).toBeNull();
  expect(screen.queryByRole('button', { name: '다음 광고' })).toBeNull();
});

it('auto-advances card slides every three seconds', () => {
  render(<Ad variant='card-large' items={[{ title: '첫 카드' }, { title: '두 번째 카드' }]} />);

  const track = screen.getByTestId('ad-track-card-large');
  expect(track.getAttribute('style')).toContain('translateX(-0%)');

  act(() => jest.advanceTimersByTime(3000));

  expect(track.getAttribute('style')).toContain('translateX(-100%)');
});

